require("dotenv").config({
  path: require("path").resolve(__dirname, "../../.env"),
});

const mongoose = require("mongoose");

const connectDB = require("../config/db");
const assert = require("assert");

const Roster = require("../models/roster");
const RosterConflict = require("../models/rosterConflict");
const Employee = require("../models/employee");
const Brand = require("../models/brand");
const Process = require("../models/process");

const {
  syncRosterConflicts,
} = require("../services/rosterConflictSync.service");

// Temporary test roster ID is generated by MongoDB.
// No existing roster or conflict records are intentionally modified.

const runTests = async () => {
  let testRosterId;

  try {
    // 1. Connect to MongoDB
    await connectDB();

    // 2. Fetch existing seeded records
    const [employee, brand, process] = await Promise.all([
      Employee.findOne({ status: "ACTIVE" }),
      Brand.findOne(),
      Process.findOne(),
    ]);

    assert(employee, "No active employee found.");
    assert(brand, "No brand found.");
    assert(process, "No process found.");

    // 3. Create a temporary test roster
    const testRoster = await Roster.create({
      name: "Conflict Synchronization Test",
      periodStart: new Date("2026-12-01T00:00:00.000Z"),
      periodEnd: new Date("2026-12-31T23:59:59.999Z"),
      status: "DRAFT",
      generatedAt: new Date(),
      totalConflicts: 0,
    });

    testRosterId = testRoster._id;

    console.log("\nTemporary roster created:", testRosterId.toString());

    // Common conflict data
    const createTestConflict = (overrides = {}) => ({
      employeeId: employee._id,
      brandId: brand._id,
      processId: process._id,
      date: new Date("2026-12-02T00:00:00.000Z"),
      type: "WEEKLY_OFF",
      severity: "HIGH",
      message: "Employee assigned on mandatory weekly off.",
      ...overrides,
    });

    // --------------------------------------------------
    // TEST 1: Create a new conflict
    // --------------------------------------------------

    console.log("\nTEST 1: Create new conflict");

    let result = await syncRosterConflicts(testRosterId, [
      createTestConflict(),
    ]);

    assert.strictEqual(result.createdCount, 1);
    assert.strictEqual(result.totalOpenConflicts, 1);
    assert.strictEqual(result.blockingConflicts, 1);

    let savedConflict = await RosterConflict.findOne({
      rosterId: testRosterId,
      type: "WEEKLY_OFF",
    });

    assert(savedConflict, "Conflict was not created.");
    assert.strictEqual(savedConflict.requiresManagerReview, true);

    console.log("PASSED: New HIGH conflict created and escalated.");

    // --------------------------------------------------
    // TEST 2: Prevent duplicate conflicts
    // --------------------------------------------------

    console.log("\nTEST 2: Prevent duplicate conflicts");

    result = await syncRosterConflicts(testRosterId, [
      createTestConflict({
        message: "Updated weekly-off message.",
      }),
    ]);

    assert.strictEqual(result.createdCount, 0);
    assert.strictEqual(result.unchangedCount, 1);

    const conflictCount = await RosterConflict.countDocuments({
      rosterId: testRosterId,
      type: "WEEKLY_OFF",
    });

    assert.strictEqual(conflictCount, 1);

    savedConflict = await RosterConflict.findOne({
      rosterId: testRosterId,
      type: "WEEKLY_OFF",
    });

    assert.strictEqual(savedConflict.message, "Updated weekly-off message.");

    console.log("PASSED: No duplicate created; existing conflict updated.");

    // --------------------------------------------------
    // TEST 3: Automatically resolve missing conflicts
    // --------------------------------------------------

    console.log("\nTEST 3: Automatically resolve conflicts");

    result = await syncRosterConflicts(testRosterId, []);

    assert.strictEqual(result.resolvedCount, 1);
    assert.strictEqual(result.totalOpenConflicts, 0);
    assert.strictEqual(result.blockingConflicts, 0);

    savedConflict = await RosterConflict.findOne({
      rosterId: testRosterId,
      type: "WEEKLY_OFF",
    });

    assert.strictEqual(savedConflict.status, "RESOLVED");
    assert.strictEqual(savedConflict.requiresManagerReview, false);

    console.log("PASSED: Undetected OPEN conflict automatically resolved.");

    // --------------------------------------------------
    // TEST 4: Do not recreate ignored conflicts
    // --------------------------------------------------

    console.log("\nTEST 4: Preserve ignored conflicts");

    const ignoredConflict = createTestConflict({
      type: "WORKING_RULE_VIOLATION",
      message: "Ignored test conflict.",
    });

    await RosterConflict.create({
      rosterId: testRosterId,
      ...ignoredConflict,
      status: "IGNORED",
      requiresManagerReview: false,
    });

    result = await syncRosterConflicts(testRosterId, [ignoredConflict]);

    assert.strictEqual(result.ignoredCount, 1);
    assert.strictEqual(result.createdCount, 0);

    const ignoredCount = await RosterConflict.countDocuments({
      rosterId: testRosterId,
      type: "WORKING_RULE_VIOLATION",
    });

    assert.strictEqual(ignoredCount, 1);

    console.log("PASSED: Ignored conflict was not recreated.");

    // --------------------------------------------------
    // TEST 5: LOW severity conflict
    // --------------------------------------------------

    console.log("\nTEST 5: LOW severity conflict");

    const lowConflict = createTestConflict({
      type: "PREFERENCE_OVERRIDDEN",
      severity: "LOW",
      message: "Preferred weekly off overridden for coverage.",
    });

    result = await syncRosterConflicts(testRosterId, [lowConflict]);

    assert.strictEqual(result.createdCount, 1);
    assert.strictEqual(result.escalatedCount, 0);
    assert.strictEqual(result.blockingConflicts, 0);

    savedConflict = await RosterConflict.findOne({
      rosterId: testRosterId,
      type: "PREFERENCE_OVERRIDDEN",
    });

    assert.strictEqual(savedConflict.severity, "LOW");
    assert.strictEqual(savedConflict.requiresManagerReview, false);
    assert.strictEqual(savedConflict.escalatedAt, null);

    console.log("PASSED: LOW conflict created without escalation.");

    // --------------------------------------------------
    // TEST 6: Escalate LOW conflict to HIGH
    // --------------------------------------------------

    console.log("\nTEST 6: Escalate LOW conflict to HIGH");

    result = await syncRosterConflicts(testRosterId, [
      createTestConflict({
        type: "PREFERENCE_OVERRIDDEN",
        severity: "HIGH",
        message: "This assignment now violates a mandatory rule.",
      }),
    ]);

    assert.strictEqual(result.createdCount, 0);
    assert.strictEqual(result.escalatedCount, 1);
    assert.strictEqual(result.blockingConflicts, 1);

    savedConflict = await RosterConflict.findOne({
      rosterId: testRosterId,
      type: "PREFERENCE_OVERRIDDEN",
    });

    assert.strictEqual(savedConflict.severity, "HIGH");
    assert.strictEqual(savedConflict.requiresManagerReview, true);
    assert(savedConflict.escalatedAt);

    console.log("PASSED: LOW conflict escalated to HIGH.");

    // --------------------------------------------------
    // TEST 7: HIGH to LOW severity change
    // --------------------------------------------------

    console.log("\nTEST 7: Change HIGH conflict to LOW");

    result = await syncRosterConflicts(testRosterId, [
      createTestConflict({
        type: "PREFERENCE_OVERRIDDEN",
        severity: "LOW",
        message: "Conflict is now only a preference warning.",
      }),
    ]);

    assert.strictEqual(result.escalatedCount, 0);
    assert.strictEqual(result.blockingConflicts, 0);

    savedConflict = await RosterConflict.findOne({
      rosterId: testRosterId,
      type: "PREFERENCE_OVERRIDDEN",
    });

    assert.strictEqual(savedConflict.severity, "LOW");
    assert.strictEqual(savedConflict.requiresManagerReview, false);

    console.log("PASSED: HIGH conflict downgraded to LOW.");

    // --------------------------------------------------
    // TEST 8: Verify roster conflict count
    // --------------------------------------------------

    console.log("\nTEST 8: Verify roster conflict count");

    const finalRoster = await Roster.findById(testRosterId);

    const actualOpenCount = await RosterConflict.countDocuments({
      rosterId: testRosterId,
      status: "OPEN",
    });

    assert.strictEqual(finalRoster.totalConflicts, actualOpenCount);

    console.log("PASSED: Roster totalConflicts matches OPEN conflict count.");

    // --------------------------------------------------
    // Final result
    // --------------------------------------------------

    console.log("\n======================================");
    console.log("ALL 8 CONFLICT SYNCHRONIZATION TESTS PASSED");
    console.log("======================================");
  } catch (error) {
    console.error("\nTEST FAILED:", error.message);
    console.error(error.stack);

    process.exitCode = 1;
  } finally {
    // Clean up only the temporary test roster and its conflicts
    if (testRosterId) {
      await RosterConflict.deleteMany({
        rosterId: testRosterId,
      });

      await Roster.deleteOne({
        _id: testRosterId,
      });

      console.log("\nTemporary test data cleaned up.");
    }

    await mongoose.disconnect();
    console.log("MongoDB disconnected.");
  }
};

runTests();
